function normalizeServiceName(value: string) {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .replace(/[^a-zA-Z0-9+.-]+/g, ' ')
    .trim()
    .toLocaleLowerCase();
}

export function resolveServiceBrand(name: string) {
  const normalized = normalizeServiceName(name);
  if (!normalized) return undefined;
  return serviceBrands.find((brand) => brand.aliases.some((alias) => {
    const candidate = normalizeServiceName(alias);
    return normalized === candidate || normalized.startsWith(`${candidate} `);
  }));
}
